# Converts the mannequin GLB generated by Meshy (Higgsfield, multi_image_to_3d) into the articulated mannequin of the
# bone sheet (assets/characters/mannequin/sheets/bones.webp):
#  - renames the bones (Hips -> Pelvis, Spine02 -> Spine_01, LeftArm -> UpperArm_L, ...) and adds a Root on the floor;
#  - cuts the shell with a plane at each joint, splits the pieces, caps their open ends and binds each piece to one
#    bone only (weight 1), so every piece turns whole, like an articulated figure;
#  - moves the spine pivots to the seams of the torso and adds the sheet's ball joints (shoulder, elbow, hip, knee,
#    ankle, neck) and two fillers in the torso;
#  - drops the animation that came with the file and sets a flat gray material (pieces) and a darker gray (joints).
# With --smooth it only renames, adds the Root and swaps the material: the skin stays Meshy's, which stretches.
# The cut heights are measured on each model (measure_meshy_model.py helps) and read from the character's cuts.json
# (--cuts); without it, the values of the first mannequin are used. Fields: name (the objects' name); seams (the top of
# Pelvis, Spine_01, Spine_03 and Neck, each a height or [height at y = 0, tilt]); v_base and v_slope (the V of the
# pelvis); neck_radius; shoulder_x; and, optional, arm_radius (near the shoulder, a face with a corner farther than this
# from the arm's axis stays with the chest).
# Usage: blender -b --factory-startup --python-exit-code 1 -P convert_meshy_mannequin.py -- in.glb out.glb
#        [--cuts cuts.json] [--smooth]
import bpy, sys, json, math
from mathutils import Vector
args = sys.argv[sys.argv.index('--') + 1:]
src, dst = args[0], args[1]; smooth = '--smooth' in args
CUTS = {"name": "Mannequin", "seams": {"Pelvis": 1.035, "Spine_01": 1.232, "Spine_03": 1.4725, "Neck": 1.525},
        "v_base": 0.895, "v_slope": 0.7, "neck_radius": 0.075, "shoulder_x": 0.155}
if '--cuts' in args:
    CUTS.update(json.load(open(args[args.index('--cuts') + 1])))
NAMES = {
    'Hips': 'Pelvis', 'Spine02': 'Spine_01', 'Spine01': 'Spine_02', 'Spine': 'Spine_03', 'neck': 'Neck', 'Head': 'Head',
    'LeftShoulder': 'Clavicle_L', 'LeftArm': 'UpperArm_L', 'LeftForeArm': 'LowerArm_L', 'LeftHand': 'Hand_L',
    'RightShoulder': 'Clavicle_R', 'RightArm': 'UpperArm_R', 'RightForeArm': 'LowerArm_R', 'RightHand': 'Hand_R',
    'LeftUpLeg': 'Thigh_L', 'LeftLeg': 'Calf_L', 'LeftFoot': 'Foot_L', 'LeftToeBase': 'Toe_L',
    'RightUpLeg': 'Thigh_R', 'RightLeg': 'Calf_R', 'RightFoot': 'Foot_R', 'RightToeBase': 'Toe_R',
}
DROPPED = {'head_end', 'headfront'}   # skinless tips that Meshy adds
bpy.ops.wm.read_factory_settings(use_empty=True)
bpy.ops.import_scene.gltf(filepath=src)
for o in list(bpy.data.objects):
    if o.type == 'MESH' and o.parent is None and o.name.startswith('Icosphere'): bpy.data.objects.remove(o)
arm = next(o for o in bpy.data.objects if o.type == 'ARMATURE')
body = next(o for o in bpy.data.objects if o.type == 'MESH')
if arm.animation_data: arm.animation_data_clear()
for a in list(bpy.data.actions): bpy.data.actions.remove(a)
missing = [n for n in NAMES if n not in arm.data.bones]
assert not missing, f"expected bones that did not come: {missing}"
# Heights of the seams, measured on each model (histogram of the vertices of the middle column): the top of each
# piece, in metres. A seam is a height, or [height at y = 0, tilt]: a tilted seam is higher at the back by tilt·y.
SEAMS = {n: v if isinstance(v, (int, float)) else v[0] for n, v in CUTS['seams'].items()}
TILT = {n: 0 if isinstance(v, (int, float)) else v[1] for n, v in CUTS['seams'].items()}
seam = lambda n, c: SEAMS[n] + TILT[n] * c.y   # height of seam n at point c
V_BASE, V_SLOPE = CUTS['v_base'], CUTS['v_slope']   # V-shaped pelvis, as in the decomposition sheet: z >= base + slope·|x|
NECK_RADIUS = CUTS['neck_radius']   # above the chest seam, farther from the axis than this is still trapezius (chest)
SHOULDER_X = CUTS['shoulder_x']     # at shoulder height, beyond this is the arm
ARM_RADIUS = CUTS.get('arm_radius')  # ...unless farther than this from the arm's axis: then it is the side of the chest
NECK_AXIS_Y = (arm.matrix_world @ arm.data.bones['neck'].head_local).y
idx2name = {g.index: g.name for g in body.vertex_groups}
if not smooth:
    # The mesh comes fused, with no edges along the seams. It is cut by a plane at each joint (a straight cut, as on an
    # articulated figure), each part is split from its neighbour and each open end gets a cap.
    import bmesh
    from collections import defaultdict
    me = body.data; M = body.matrix_world.copy(); AW = arm.matrix_world
    H = lambda n: AW @ arm.data.bones[n].head_local
    D = lambda n: ((AW @ arm.data.bones[n].tail_local) - H(n)).normalized()
    bm = bmesh.new(); bm.from_mesh(me); bm.transform(M)
    bmesh.ops.remove_doubles(bm, verts=bm.verts[:], dist=1e-5)      # Meshy splits the faces along the normals
    dl = bm.verts.layers.deform.active
    REG = bm.faces.layers.int.new('region')   # 0 torso, 1/2 shoulder L/R, 3/4 arm L/R, 5/6 leg L/R
    ARM = {'Arm', 'ForeArm', 'Hand'}; LEG = {'UpLeg', 'Leg', 'Foot', 'ToeBase'}
    for f in bm.faces:
        total = defaultdict(float)
        for v in f.verts:
            for gi, w in v[dl].items(): total[idx2name[gi]] += w
        n = max(total, key=total.get) if total else 'Hips'
        side = 0 if n.startswith('Left') else 1 if n.startswith('Right') else None
        base = n.replace('Left', '').replace('Right', '')
        f[REG] = (0 if side is None else 1 + side if base == 'Shoulder' else 3 + side if base in ARM
                  else 5 + side if base in LEG else 0)
    planes = {}
    for s_, P, sg in (('L', 'Left', 1), ('R', 'Right', -1)):
        k = 0 if s_ == 'L' else 1
        planes['wrist' + s_] = ({3 + k}, H(P + 'Hand'), D(P + 'ForeArm'))
        planes['elbow' + s_] = ({3 + k}, H(P + 'ForeArm'), (D(P + 'Arm') + D(P + 'ForeArm')).normalized())
        planes['shoulder' + s_] = ({1 + k}, Vector((sg * SHOULDER_X, 0, 0)), Vector((sg, 0, 0)))
        planes['hip' + s_] = ({5 + k, 0}, Vector((0, 0, V_BASE)), Vector((-V_SLOPE * sg, 0, 1)).normalized())
        planes['knee' + s_] = ({5 + k}, H(P + 'Leg'), (D(P + 'UpLeg') + D(P + 'Leg')).normalized())
        planes['ankle' + s_] = ({5 + k}, H(P + 'Foot') - D(P + 'Leg') * 0.02, D(P + 'Leg'))
    for name, z in SEAMS.items():
        nrm = Vector((0, -TILT[name], 1)).normalized() if TILT[name] else Vector((0, 0, 1))
        planes['seam_' + name] = ({0, 1, 2, 5, 6}, Vector((0, 0, z)), nrm)
    for name, (regs, co, no) in planes.items():
        fs = [f for f in bm.faces if f[REG] in regs]
        if name.startswith('hip'):   # the V of the pelvis applies only on its own side and below the seam
            sg = 1 if name.endswith('L') else -1
            fs = [f for f in fs if f[REG] != 0 or (sg * f.calc_center_median().x > -0.01
                                                   and f.calc_center_median().z < seam('Pelvis', f.calc_center_median()) + 0.03)]
        es = {e for f in fs for e in f.edges}; vs = {v for f in fs for v in f.verts}
        bmesh.ops.bisect_plane(bm, geom=list(vs) + list(es) + fs, dist=1e-6, plane_co=co, plane_no=no)
    beyond = lambda name, c: (c - planes[name][1]).dot(planes[name][2]) > 0
    def off_arm(f, s_):   # a face near the shoulder with a corner far from the arm's axis is the side of the chest
        if ARM_RADIUS is None: return False
        P = 'Left' if s_ == 'L' else 'Right'; h, d = H(P + 'Arm'), D(P + 'Arm')
        if (f.calc_center_median() - h).dot(d) >= 0.12: return False
        return max(((v.co - h) - d * (v.co - h).dot(d)).length for v in f.verts) > ARM_RADIUS
    def piece(f):
        c = f.calc_center_median(); r = f[REG]; s_ = 'L' if c.x > 0 else 'R'
        if r in (3, 4):
            s_ = 'L' if r == 3 else 'R'
            if beyond('wrist' + s_, c): return 'Hand_' + s_
            if beyond('elbow' + s_, c): return 'LowerArm_' + s_
            return 'Spine_03' if off_arm(f, s_) else 'UpperArm_' + s_
        if r in (5, 6) and c.z < seam('Pelvis', c):
            s_ = 'L' if r == 5 else 'R'
            if beyond('ankle' + s_, c): return 'Foot_' + s_
            if beyond('knee' + s_, c): return 'Calf_' + s_
            if beyond('hip' + s_, c) and c.z < seam('Pelvis', c) + 0.01: return 'Pelvis'
            return 'Thigh_' + s_
        if r in (1, 2) and abs(c.x) > SHOULDER_X and not off_arm(f, s_): return 'UpperArm_' + s_
        if r in (5, 6) and beyond('ankle' + s_, c): return 'Foot_' + s_
        if c.z < seam('Pelvis', c): return 'Pelvis' if beyond('hip' + s_, c) else 'Thigh_' + s_
        if c.z < seam('Spine_01', c): return 'Spine_01'
        if c.z < seam('Spine_03', c): return 'Spine_03'
        if c.z < seam('Neck', c): return 'Neck' if math.hypot(c.x, c.y - NECK_AXIS_Y) < NECK_RADIUS else 'Spine_03'
        return 'Head'
    PIECES = sorted(set(NAMES.values()) - {'Toe_L', 'Toe_R'})
    PC = bm.faces.layers.int.new('piece')
    for f in bm.faces: f[PC] = PIECES.index(piece(f))
    # an island of fewer than 8 faces goes to the neighbouring piece that surrounds it most
    seen = set()
    for f in bm.faces:
        if f in seen: continue
        island = []; stack = [f]; seen.add(f)
        while stack:
            g = stack.pop(); island.append(g)
            for e in g.edges:
                for h in e.link_faces:
                    if h not in seen and h[PC] == f[PC]: seen.add(h); stack.append(h)
        if len(island) < 8:
            around = defaultdict(int)
            for g in island:
                for e in g.edges:
                    for h in e.link_faces:
                        if h[PC] != f[PC]: around[h[PC]] += 1
            if around:
                new = max(around, key=around.get)
                for g in island: g[PC] = new
    seams = [e for e in bm.edges if len(e.link_faces) == 2 and e.link_faces[0][PC] != e.link_faces[1][PC]]
    bmesh.ops.split_edges(bm, edges=seams)
    # Only a flat opening (the straight cut of a plane) gets a cap. A crooked one would become a fan of spikes and
    # stays open: the ball joint hides it.
    border = [e for e in bm.edges if len(e.link_faces) == 1]
    parent = {}
    def root_of(v):
        while parent.get(v, v) is not v: v = parent[v]
        return v
    for e in border:
        a_, b_ = root_of(e.verts[0]), root_of(e.verts[1])
        if a_ is not b_: parent[a_] = b_
    openings = defaultdict(list)
    for e in border: openings[root_of(e.verts[0])].append(e)
    caps = []; left_open = 0
    for es in openings.values():
        vs = list({v for e in es for v in e.verts}); c = sum((v.co for v in vs), Vector()) / len(vs)
        nrm = Vector()
        for e in es: nrm += (e.verts[0].co - c).cross(e.verts[1].co - c)
        flat = nrm.length > 1e-9 and max(abs((v.co - c).dot(nrm.normalized())) for v in vs) < 0.004
        if flat: caps += bmesh.ops.holes_fill(bm, edges=es, sides=0)['faces']
        else: left_open += 1; print(f"OPEN_GAP centre=({c.x:+.3f},{c.y:+.3f},{c.z:.3f}) edges={len(es)}")
    for f in caps:
        nb = [g for e in f.edges for g in e.link_faces if g is not f]
        if nb: f[PC] = nb[0][PC]
    bmesh.ops.delete(bm, geom=[v for v in bm.verts if not v.link_faces], context='VERTS')
    bm.verts.index_update()
    vp = {v.index: PIECES[v.link_faces[0][PC]] for v in bm.verts}
    bm.transform(M.inverted()); bm.to_mesh(me); bm.free()
    for g in body.vertex_groups: g.remove(range(len(me.vertices)))
    old_of = {new: old for old, new in NAMES.items()}   # the groups keep Meshy's names until the bones are renamed
    for i, n in vp.items():
        body.vertex_groups[old_of[n]].add([i], 1.0, 'REPLACE')
    print(f"CUT openings={len(openings)} cap_faces={len(caps)} left_open={left_open}")
# skeleton: the sheet's names, Root on the floor, without the extra tips
bpy.context.view_layer.objects.active = arm
bpy.ops.object.mode_set(mode='EDIT')
eb = arm.data.edit_bones
for n in DROPPED:
    if n in eb: eb.remove(eb[n])
MWi = arm.matrix_world.inverted()   # Meshy stores the skeleton in centimetres, with the object at scale 0.01
root = eb.new('Root'); root.head = MWi @ Vector((0, 0, 0)); root.tail = MWi @ Vector((0, 0.15, 0))   # on the floor, pointing back
for b in eb: b.use_connect = False
eb['Hips'].parent = root
if not smooth:
    # Spine pivots at the seams of the torso: the abdomen turns on its seam with the pelvis, the chest on its seam with
    # the abdomen (Spine_02) and a little above it (Spine_03). Meshy puts them in the middle of the pieces, and the
    # seam slid.
    for old, z in (('Spine02', SEAMS['Pelvis']), ('Spine01', SEAMS['Spine_01']), ('Spine', SEAMS['Spine_01'] + 0.06)):
        b = eb[old]; d = b.tail - b.head; h = arm.matrix_world @ b.head; h.z = z; b.head = MWi @ h; b.tail = b.head + d
bpy.ops.object.mode_set(mode='OBJECT')
for old, new in NAMES.items():
    arm.data.bones[old].name = new           # Blender renames the vertex groups along with the bones
arm.data.bones['Root'].use_deform = False
for g in list(body.vertex_groups):
    if g.name in DROPPED: body.vertex_groups.remove(g)
arm.name = CUTS['name']; arm.data.name = CUTS['name'] + '_rig'; body.name = CUTS['name'] + '_body'
def material(name, colour):
    m = bpy.data.materials.new(name); m.use_nodes = True
    p = next(n for n in m.node_tree.nodes if n.type == 'BSDF_PRINCIPLED')
    p.inputs['Base Color'].default_value = (*colour, 1); p.inputs['Roughness'].default_value = 0.65
    return m
body.data.materials.clear(); body.data.materials.append(material('gray', (0.42, 0.43, 0.45)))
joints = []
if not smooth:
    # The sheet's ball joints (Shoulder, HipJoint, KneeJoint and the small ones at the elbow and ankle, plus the neck)
    # and two fillers in the torso. Meshy's shell is one piece: split into pieces, it opens a hole when a joint bends.
    # Each ball sits on the bone's pivot, so turning does not show it; it only shows where a piece moves away.
    import bmesh
    from collections import defaultdict
    MW, BW = arm.matrix_world, body.matrix_world
    gidx = {g.index: g.name for g in body.vertex_groups}
    points = defaultdict(list)
    for v in body.data.vertices:
        if v.groups: points[gidx[v.groups[0].group]].append(BW @ v.co)
    head_of = lambda n: MW @ arm.data.bones[n].head_local
    dir_of = lambda n: ((MW @ arm.data.bones[n].tail_local) - (MW @ arm.data.bones[n].head_local)).normalized()
    def section(piece, J, d, a, b, q=0.3):   # radius of the piece's section between a and b metres from the pivot, along d
        rs = sorted(((p - J) - d * (p - J).dot(d)).length for p in points[piece] if a <= (p - J).dot(d) <= b)
        return rs[int(len(rs) * q)] if rs else 1.0
    jmat = material('joint', (0.30, 0.31, 0.33))
    def ball(name, bone, centre, radii):
        m = bpy.data.meshes.new(name); bm = bmesh.new()
        bmesh.ops.create_icosphere(bm, subdivisions=2, radius=1.0)
        for v in bm.verts: v.co = Vector((v.co.x * radii[0], v.co.y * radii[1], v.co.z * radii[2])) + centre
        bm.to_mesh(m); bm.free(); m.materials.append(jmat)
        o = bpy.data.objects.new(name, m); bpy.context.scene.collection.objects.link(o)
        o.vertex_groups.new(name=bone).add(range(len(m.vertices)), 1.0, 'REPLACE')
        joints.append((name, bone, [round(r, 3) for r in radii])); return o
    new_objects = []
    def radii_of_side(s_):
        e = {}
        J = head_of('UpperArm_' + s_); e['Shoulder'] = section('UpperArm_' + s_, J, dir_of('UpperArm_' + s_), 0.0, 0.05)
        J = head_of('LowerArm_' + s_); e['ElbowJoint'] = max(section('UpperArm_' + s_, J, dir_of('UpperArm_' + s_), -0.04, 0.0),
                                                            section('LowerArm_' + s_, J, dir_of('LowerArm_' + s_), 0.0, 0.04))
        J = head_of('Thigh_' + s_); e['HipJoint'] = 0.8 * section('Thigh_' + s_, J, dir_of('Thigh_' + s_), 0.03, 0.09)
        J = head_of('Calf_' + s_); e['KneeJoint'] = max(section('Thigh_' + s_, J, dir_of('Thigh_' + s_), -0.05, 0.0),
                                                       section('Calf_' + s_, J, dir_of('Calf_' + s_), 0.0, 0.05))
        J = head_of('Foot_' + s_); e['AnkleJoint'] = section('Calf_' + s_, J, dir_of('Calf_' + s_), -0.10, 0.0)
        return e
    RL, RR = radii_of_side('L'), radii_of_side('R')
    BONE_OF_JOINT = {'Shoulder': 'UpperArm_', 'ElbowJoint': 'LowerArm_', 'HipJoint': 'Thigh_', 'KneeJoint': 'Calf_', 'AnkleJoint': 'Foot_'}
    for kind, prefix in BONE_OF_JOINT.items():
        r = (RL[kind] + RR[kind]) / 2          # Meshy's mesh is not symmetric; the joints are
        for s_ in 'LR':
            new_objects.append(ball(kind + '_' + s_, prefix + s_, head_of(prefix + s_), (r,) * 3))
    J = head_of('Neck'); r = section('Neck', J, dir_of('Neck'), 0.0, 0.05)
    new_objects.append(ball('NeckJoint', 'Neck', J, (r,) * 3))
    for name, bone, z0, z1 in (('Waist', 'Spine_01', SEAMS['Spine_01'] - 0.05, SEAMS['Spine_01']),
                               ('Belly', 'Pelvis', SEAMS['Pelvis'], SEAMS['Pelvis'] + 0.05)):
        ps = [p for p in points['Spine_01'] if z0 <= p.z <= z1]
        xs = sorted(abs(p.x) for p in ps); ys = [p.y for p in ps]
        c = Vector((0, (max(ys) + min(ys)) / 2, (SEAMS['Spine_01'] if name == 'Waist' else SEAMS['Pelvis'])))
        new_objects.append(ball(name, bone, c, (xs[int(len(xs) * 0.8)] * 0.92, (max(ys) - min(ys)) / 2 * 0.85, 0.06)))
    for o in bpy.data.objects: o.select_set(False)
    for o in new_objects: o.select_set(True)
    body.select_set(True); bpy.context.view_layer.objects.active = body
    bpy.ops.object.join()
    body.data.polygons.foreach_set("use_smooth", [False] * len(body.data.polygons))
bpy.ops.export_scene.gltf(filepath=dst, export_format='GLB', export_skins=True, export_animations=False,
                          export_apply=False, export_yup=True)
report = {"output": dst, "weights": "smooth" if smooth else "rigid", "triangles": sum(len(f.vertices) - 2 for f in body.data.polygons),
          "joints": joints, "bones": [(b.name, b.parent.name if b.parent else None) for b in arm.data.bones]}
print("RESULT " + json.dumps(report))
